class Solution {
    public int numRescueBoats(int[] people, int limit) {
        Arrays.sort(people);

        int len = people.length;
        int left = 0,  right = len-1;
        int boat = 0;

        while (left <= right){
            if (people[left] + people[right] <= limit){
                left++;
            }
            right--;
            boat++;
        }
        return boat;
    }
}
